{
  "id": "R1",
  "summary_ko": "물방울이 바람 속에서 떨어지지 않는다.",
  "claims": [
    {
      "id": "R1.S1",
      "evidence": "the water droplets dont fall in the wind",
      "symptom_ko": "물방울이 바람 속에서 떨어지지 않음",
      "is_anomaly": true,
      "specificity": "specific",
      "target_evidence": "the water droplets",
      "explicit_detail_evidence": [
        "dont fall in the wind"
      ],
      "missing_details_ko": ""
    }
  ]
}

{
  "id": "R2",
  "summary_ko": "바람의 세기에 비추어 볼 때 잎에 맺힌 이슬방울이 식물 잎에서 떨어져야 한다.",
  "claims": [
    {
      "id": "R2.S1",
      "evidence": "Based upon the wind strength, the dew drops on the leaves should be dripping from the plant leaves.",
      "symptom_ko": "바람 세기를 고려할 때 잎 위의 이슬방울이 잎에서 떨어져야 함(떨어지지 않음).",
      "is_anomaly": true,
      "specificity": "specific",
      "target_evidence": "the dew drops on the leaves",
      "explicit_detail_evidence": [
        "should be dripping from the plant leaves"
      ],
      "missing_details_ko": ""
    }
  ]
}

{
  "pairs": [
    {
      "reference_id": "R2",
      "candidate_id": "C1",
      "target_relation": "same",
      "reference_claim_ids": [
        "R2.S1"
      ],
      "reference_evidence": "the dew drops on the leaves should be dripping from the plant leaves",
      "candidate_evidence": "Dewdrops on the prominent foreground grass stalk shift, flicker, and warp intermittently as the camera tracks",
      "basis": "explicit_separation",
      "reason_ko": "레퍼런스는 바람에 의해 이슬방울이 떨어져야 한다는 물리적 동작(흘러내림) 결여를 구체적 결함으로 기술하고 있는 반면, 후보 C1은 카메라 이동에 따른 이슬방울의 시각적 왜곡(깜빡임, 워핑, 불규칙 이동)을 기술하여 서로 명확히 구분되는 구체적 결함을 다루고 있습니다."
    },
    {
      "reference_id": "R2",
      "candidate_id": "C2",
      "target_relation": "same",
      "reference_claim_ids": [
        "R2.S1"
      ],
      "reference_evidence": "the dew drops on the leaves should be dripping from the plant leaves",
      "candidate_evidence": "Dewdrops on the foreground horizontal wheat spike morph, change size, and flicker erratically as the blade sways",
      "basis": "explicit_separation",
      "reason_ko": "레퍼런스는 바람 세기 대비 이슬방울의 낙하 동작 부재를 지적하는 물리적 결함인 반면, 후보 C2는 풀잎이 흔들릴 때 발생하는 이슬방울의 형태 변형, 크기 변화, 깜빡임이라는 렌더링/시각적 왜곡 결함을 지적하므로 두 결함이 명확히 구별됩니다."
    },
    {
      "reference_id": "R2",
      "candidate_id": "C3",
      "target_relation": "different",
      "reference_claim_ids": [
        "R2.S1"
      ],
      "reference_evidence": "the dew drops on the leaves",
      "candidate_evidence": "Background grass stalks and awns along the horizon",
      "basis": "explicit_separation",
      "reason_ko": "레퍼런스의 대상은 잎 위의 이슬방울(the dew drops on the leaves)인 반면, 후보 C3의 대상은 지평선 부근의 배경 풀 줄기와 까락(Background grass stalks and awns)으로 대상 자체가 서로 다릅니다."
    }
  ]
}

